class Solution {
    public int uniquePaths(int m, int n) {
        int[][] dp = new int[m][n];
        for (int row = 0; row < m; row++) {
            dp[row][0] = 1;
        }
        for (int col = 0; col < n; col++) {
            dp[0][col] = 1;
        }

        for (int row = 1; row < m; row++) {
            for (int col = 1; col < n; col++) {
                dp[row][col] = dp[row - 1][col] + dp[row][col - 1];
            }
        }
        return dp[m - 1][n - 1];
    }
}

class Solution {
    public int uniquePaths(int m, int n) {
        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1);

        for (int row = 1; row < m; row++) {
            for (int col = 1; col < n; col++) {
                dp[col] += dp[col - 1];
            }
        }
        return dp[n - 1];
    }
}

class Solution {
    public int uniquePaths(int m, int n) {
        int[][] memo = new int[m][n];
        return paths(0, 0, m, n, memo);
    }

    private int paths(int row, int col, int m, int n, int[][] memo) {
        if (row == m - 1 || col == n - 1) {
            return 1;
        }
        if (memo[row][col] != 0) {
            return memo[row][col];
        }

        memo[row][col] = paths(row + 1, col, m, n, memo)
                + paths(row, col + 1, m, n, memo);
        return memo[row][col];
    }
}

class Solution {
    public int uniquePaths(int m, int n) {
        int down = m - 1;
        int right = n - 1;
        int choose = Math.min(down, right);
        int totalMoves = down + right;

        long result = 1;
        for (int step = 1; step <= choose; step++) {
            result = result * (totalMoves - choose + step) / step;
        }
        return (int) result;
    }
}

class Solution {
    public int uniquePaths(int m, int n) {
        int[][] ways = new int[m][n];
        ways[0][0] = 1;

        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                if (row + 1 < m) {
                    ways[row + 1][col] += ways[row][col];
                }
                if (col + 1 < n) {
                    ways[row][col + 1] += ways[row][col];
                }
            }
        }
        return ways[m - 1][n - 1];
    }
}
